def search_numista(query):
    try:
        resp = requests.get(
            API_URL,
            headers=HEADERS,
            params={"q": query, "category": "coin", "count": 5},
            timeout=15,
        )
        resp.raise_for_status()
        return resp.json().get("types", [])
    except Exception as e:
        print(f"  Erreur pour '{query}': {e}")
        return []

def main():
    coins = COINS[:TEST_LIMIT] if TEST_LIMIT else COINS
    print(f"Traitement de {len(coins)} pièces...")

    with open("numista_matches.csv", "w", newline="", encoding="utf-8") as out:
        writer = csv.writer(out)
        writer.writerow([
            "year", "country_slug", "country_name", "our_name", "image_url",
            "candidate_rank", "numista_id", "candidate_title",
            "candidate_issuer", "candidate_years", "candidate_thumbnail",
        ])

        for i, (year, slug, country_name, name, url) in enumerate(coins, 1):
            # Requête : pays + année + premiers mots de la raison d'émission
            # (évite les requêtes trop longues/bruitées)
            short_name = " ".join(name.split()[:6])
            query = f"2 euro {country_name} {year} {short_name}"
            candidates = search_numista(query)

            if not candidates:
                writer.writerow([year, slug, country_name, name, url, "", "", "AUCUN RESULTAT", "", "", ""])
            else:
                for rank, c in enumerate(candidates, 1):
                    writer.writerow([
                        year, slug, country_name, name, url,
                        rank,
                        c.get("id", ""),
                        c.get("title", ""),
                        (c.get("issuer") or {}).get("name", ""),
                        f"{c.get('min_year', '')}-{c.get('max_year', '')}",
                        c.get("obverse_thumbnail", ""),
                    ])

            if i % 20 == 0:
                print(f"{i}/{len(coins)}...")
            time.sleep(0.4)  # reste large sous les limites de l'API

    print("Terminé. Résultats dans numista_matches.csv — à ouvrir dans Excel/Google Sheets pour vérifier les correspondances.")

if __name__ == "__main__":
    main()
